'use strict'

const DEFAULT_MAX_TIME_MS = 8
const DEFAULT_MAX_LAYERS = 100
const DEFAULT_MAX_YIELDS = 1000

module.exports = {
  createDispatchState,
  normalizeCooperativeDispatch
}

function normalizeCooperativeDispatch (value) {
  if (!value) {
    return null
  }

  if (value === true) {
    value = {}
  }

  if (typeof value !== 'object') {
    value = {}
  }

  return {
    enabled: value.enabled !== false,
    maxTimeMs: value.maxTimeMs != null ? value.maxTimeMs : DEFAULT_MAX_TIME_MS,
    maxLayers: value.maxLayers != null ? value.maxLayers : DEFAULT_MAX_LAYERS,
    maxYields: value.maxYields != null ? value.maxYields : DEFAULT_MAX_YIELDS
  }
}

function createDispatchState (req, res, config) {
  if (!config || config.enabled === false) {
    return null
  }

  ensureDispatchListeners(req, res)

  return {
    config,
    layers: 0,
    yields: 0,
    start: process.hrtime.bigint(),
    shouldYield: function shouldYield () {
      if (req._cooperativeDispatchAborted) {
        return false
      }

      if (this.yields >= this.config.maxYields) {
        return false
      }

      if (this.config.maxLayers != null && this.layers >= this.config.maxLayers) {
        return true
      }

      if (this.config.maxTimeMs != null) {
        const now = process.hrtime.bigint()
        const elapsedMs = Number(now - this.start) / 1e6
        if (elapsedMs >= this.config.maxTimeMs) {
          return true
        }
      }

      return false
    },
    onLayer: function onLayer () {
      this.layers++
    },
    reset: function reset () {
      this.layers = 0
      this.start = process.hrtime.bigint()
    },
    defer: function defer (next, err) {
      if (req._cooperativeDispatchAborted) {
        return
      }

      if (this.yields >= this.config.maxYields) {
        return next(err)
      }

      this.yields++
      this.reset()
      setImmediate(function () {
        if (!req._cooperativeDispatchAborted) {
          next(err)
        }
      })
    }
  }
}

function ensureDispatchListeners (req, res) {
  if (req._cooperativeDispatchListeners) {
    return
  }

  req._cooperativeDispatchListeners = true

  function onClose () {
    req._cooperativeDispatchAborted = true
  }

  if (typeof req.on === 'function') {
    req.on('aborted', onClose)
  }

  if (typeof res.on === 'function') {
    res.on('close', onClose)
  }
}
